import { scaleLinear } from '@visx/scale';
import React from 'react';

import { WithChildren } from '../../../core/types/with-children.js';
import { XYChartColorScaleContext } from '../context/XYChartColorScale.context.js';
import { useXYChartData } from '../hooks/useXYChartData.js';

export const XYChartColorScaleProvider = ({ children }: WithChildren) => {
  const { minMaxValue } = useXYChartData();

  const scaleColor = scaleLinear({
    domain: [minMaxValue.min, minMaxValue.max],
    range: ['purple', 'green'],
  });

  return (
    <XYChartColorScaleContext.Provider value={scaleColor}>
      {children}
    </XYChartColorScaleContext.Provider>
  );
};

XYChartColorScaleProvider['displayName'] = 'XYChartColorScaleProvider';
